const html = String($input.first().json.data || $input.first().json.body || '');
const updates = [];
const seen = new Set();

function cleanText(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const updateRegex = /<summary[^>]*class=["'][^"']*e-n-accordion-item-title[^"']*["'][^>]*>[\s\S]{0,1200}?class=["']e-n-accordion-item-title-text["'][^>]*>([\s\S]*?)<\/div>[\s\S]*?<\/summary>/gi;
let match;

while ((match = updateRegex.exec(html)) !== null && updates.length < 12) {
  const title = cleanText(match[1]);
  if (!title || title.length < 8 || seen.has(title.toLowerCase())) continue;

  const followingHtml = html.slice(updateRegex.lastIndex, updateRegex.lastIndex + 4000);
  const descriptionMatch = followingHtml.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
  const description = cleanText(descriptionMatch?.[1]).substring(0, 1000);
  seen.add(title.toLowerCase());
  updates.push({
    title: title.substring(0, 200),
    content: description || title,
    source: 'cype-generador-precios',
    metadata: {
      url: 'https://info.cype.com/es/programa_relacionado/generador-de-precios/',
      captured_at: new Date().toISOString()
    }
  });
}

if (updates.length === 0) return [];
return [{ json: { cype_updates: updates } }];

const xml = String($input.first().json.data || $input.first().json.body || '');
const regulations = [];
const seen = new Set();
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
const titleRegex = /<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([\s\S]*?)<\/title>/i;
const descRegex = /<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>|<description>([\s\S]*?)<\/description>/i;
const linkRegex = /<link>([^<]+)<\/link>/i;
const keywords = [
  'construcci', 'edific', 'vivienda', 'urbanis', 'reforma',
  'instalaci', 'electric', 'fontaner', 'climat', 'residuo',
  'seguridad', 'laboral', 'prevenci', 'eficiencia energ'
];

function cleanText(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

let match;
while ((match = itemRegex.exec(xml)) !== null && regulations.length < 20) {
  const item = match[1];
  const titleMatch = item.match(titleRegex) || [];
  const descMatch = item.match(descRegex) || [];
  const title = cleanText(titleMatch[1] || titleMatch[2]);
  const description = cleanText(descMatch[1] || descMatch[2]);
  const url = cleanText((item.match(linkRegex) || [])[1]);
  const searchable = (title + ' ' + description).toLowerCase();

  if (
    !title ||
    seen.has(title.toLowerCase()) ||
    !keywords.some((keyword) => searchable.includes(keyword))
  ) {
    continue;
  }

  seen.add(title.toLowerCase());
  regulations.push({
    title: title.substring(0, 200),
    description: description.substring(0, 1_000),
    source: 'boe-rss',
    metadata: {
      url,
      captured_at: new Date().toISOString()
    }
  });
}

if (regulations.length === 0) return [];
return [{ json: { regulations } }];

const xml = String($input.first().json.data || $input.first().json.body || '');
const news = [];
const seen = new Set();
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
const titleRegex = /<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>|<title>([\s\S]*?)<\/title>/i;
const linkRegex = /<link>([^<]+)<\/link>/i;
const pubDateRegex = /<pubDate>([^<]+)<\/pubDate>/i;

function cleanText(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

let match;
while ((match = itemRegex.exec(xml)) !== null && news.length < 10) {
  const item = match[1];
  const titleMatch = item.match(titleRegex) || [];
  const title = cleanText(titleMatch[1] || titleMatch[2]);
  const url = cleanText((item.match(linkRegex) || [])[1]);
  const publishedAt = cleanText((item.match(pubDateRegex) || [])[1]);

  if (!title || seen.has(title.toLowerCase())) continue;
  seen.add(title.toLowerCase());
  news.push({
    title: title.substring(0, 200),
    content: publishedAt ? 'Fecha de publicación: ' + publishedAt : '',
    source: 'google-news-rss',
    metadata: {
      url,
      published_at: publishedAt,
      captured_at: new Date().toISOString()
    }
  });
}

if (news.length === 0) return [];
return [{ json: { news } }];

const inputItems = $input.all().map((item) => item.json);
const ineData =
  inputItems.length === 1 && Array.isArray(inputItems[0])
    ? inputItems[0]
    : inputItems.flatMap((item) => Array.isArray(item) ? item : [item]);
const signals = [];
const capturedAt = new Date().toISOString();

for (const series of ineData.slice(0, 25)) {
  const name = String(series.Nombre || series.nombre || '')
    .replace(/<[^>]*>/g, '')
    .trim();
  const points = Array.isArray(series.Data || series.data)
    ? (series.Data || series.data)
    : [];

  if (!name || points.length === 0) continue;
  const current = Number(points[0].Valor ?? points[0].valor);
  const previous =
    points.length > 1 ? Number(points[1].Valor ?? points[1].valor) : null;
  if (!Number.isFinite(current)) continue;

  const variation =
    Number.isFinite(previous) && previous !== 0
      ? ((current - previous) / previous) * 100
      : null;

  signals.push({
    name: name.substring(0, 180),
    value: current,
    previous_value: Number.isFinite(previous) ? previous : null,
    variation_pct:
      variation === null ? null : Number(variation.toFixed(2)),
    unit: 'index',
    source: 'INE-API',
    description:
      variation === null
        ? 'Índice INE: ' + name
        : 'Índice INE: ' + name + '. Variación: ' + variation.toFixed(2) + '%',
    captured_at: capturedAt
  });
}

if (signals.length === 0) return [];
return [{ json: { market_signals: signals } }];

const response = $input.first().json;
const included = Array.isArray(response.included) ? response.included : [];
const pvpc = included.find((item) => {
  const title = String(item?.attributes?.title || item?.type || '').toLowerCase();
  return title === 'pvpc' || title.includes('precio voluntario');
});

const values = Array.isArray(pvpc?.attributes?.values)
  ? pvpc.attributes.values
      .map((item) => ({
        value: Number(item?.value),
        datetime: item?.datetime || null
      }))
      .filter((item) => Number.isFinite(item.value) && item.value >= 0)
  : [];

if (values.length === 0) return [];

const capturedAt = new Date().toISOString();
const numericValues = values.map((item) => item.value);
const average = numericValues.reduce((sum, value) => sum + value, 0) / numericValues.length;
const minimum = Math.min(...numericValues);
const maximum = Math.max(...numericValues);
const metadata = {
  period_start: values[0]?.datetime || null,
  period_end: values[values.length - 1]?.datetime || null,
  sample_count: values.length,
  captured_at: capturedAt,
  api_title: response?.data?.attributes?.title || null
};

const signals = [
  {
    name: 'electricidad_pvpc_media_hoy',
    value: Number(average.toFixed(4)),
    description: 'Precio medio diario PVPC de electricidad en España'
  },
  {
    name: 'electricidad_pvpc_max_hoy',
    value: maximum,
    description: 'Precio máximo diario PVPC de electricidad en España'
  },
  {
    name: 'electricidad_pvpc_min_hoy',
    value: minimum,
    description: 'Precio mínimo diario PVPC de electricidad en España'
  }
].map((item) => ({
    ...item,
    unit: 'EUR/MWh',
    source: 'REE-REData-PVPC',
    metadata
  }));

return [{ json: { market_signals: signals } }];

const items = Array.isArray($json.cype_updates) ? $json.cype_updates : [];
const news = items
  .filter((item) => item && typeof item.title === 'string' && item.title.trim())
  .map((item) => ({
    title: item.title.trim().substring(0, 200),
    content: item.content || item.description || 'Novedad de CYPE.',
    source: item.source || 'cype-generador-precios',
    metadata: item.metadata || {}
  }));

if (news.length === 0) return [];
return [{
  json: {
    action: 'update_news',
    sector: 'construccion',
    data: { news }
  }
}];

const items = Array.isArray($json.market_signals)
  ? $json.market_signals
  : [];
const prices = items
  .filter((item) => item && item.name && Number.isFinite(Number(item.value)))
  .map((item) => ({
    title: item.name,
    value: Number(item.value),
    unit: item.unit || 'EUR/MWh',
    category: 'energia',
    subcategory: 'electricidad',
    source: item.source || 'REE-REData-PVPC',
    description: item.description || '',
    metadata: item.metadata || { captured_at: new Date().toISOString() }
  }));

if (prices.length === 0) return [];
return [{
  json: {
    action: 'update_prices',
    sector: 'construccion',
    data: {
      source_group: 'REE-REData-PVPC',
      prices
    }
  }
}];

const items = Array.isArray($json.news) ? $json.news : [];
const news = items
  .filter((item) => item && typeof item.title === 'string' && item.title.trim())
  .map((item) => ({
    title: item.title.trim().substring(0, 200),
    content: item.content || item.description || '',
    source: item.source || 'google-news-rss',
    metadata: item.metadata || {}
  }));

if (news.length === 0) return [];
return [{
  json: {
    action: 'update_news',
    sector: 'construccion',
    data: { news }
  }
}];

const items = Array.isArray($json.regulations) ? $json.regulations : [];
const regulations = items
  .filter((item) => item && typeof item.title === 'string' && item.title.trim())
  .map((item) => ({
    title: item.title.trim().substring(0, 200),
    description: item.description || '',
    source: item.source || 'boe-rss',
    metadata: item.metadata || {}
  }));

if (regulations.length === 0) return [];
return [{
  json: {
    action: 'update_regulations',
    sector: 'construccion',
    data: { regulations }
  }
}];

const items = Array.isArray($json.market_signals)
  ? $json.market_signals
  : [];
const prices = items
  .filter((item) => Number.isFinite(Number(item.value)))
  .slice(0, 25)
  .map((item) => ({
    title: item.title || item.name,
    value: Number(item.value),
    unit: item.unit || 'index',
    category: 'indice_mercado',
    subcategory: item.subcategory || 'INE',
    source: item.source || 'INE-API',
    description: item.description || '',
    metadata: {
      previous_value: item.previous_value ?? null,
      variation_pct: item.variation_pct ?? null,
      captured_at: item.captured_at || new Date().toISOString()
    }
  }))
  .filter((item) => item.title);

if (prices.length === 0) {
  return [{
    json: {
      skip_send: true,
      reason: 'No hay índices INE válidos para enviar'
    }
  }];
}

return [{
  json: {
    action: 'update_prices',
    sector: 'construccion',
    data: {
      source_group: 'INE-indices-construccion',
      prices
    }
  }
}];
